class Solution {
  private TreeNode previous;

  public void flatten(TreeNode root) {
    // reverse preorder (right, left, node) links each node to the one that follows it in preorder
    if (root == null) return;
    flatten(root.right);
    flatten(root.left);
    root.right = previous;
    root.left = null;
    previous = root;
  }
}
